 rate_text:=flag.String("rate","c0","exact fast12 rate hex");profile:=flag.String("profile","am","am or carrier");column:=flag.String("column","linear","linear,left,right");start:=flag.Int("start-sample",3072,"actual externallyqualified post lowerbound");pre:=flag.Int("pre-end-sample",512,"direct guaranteed resetheld prefix");output:=flag.String("output","","exclusive JSON output");curve:=flag.String("curve","","optional exclusive unaligned projectioncurve");flag.Parse()
